import { Fragment, type ReactNode } from 'react'
import { SiteHeader } from '@/components/site/SiteHeader'
import { SiteFooter } from '@/components/site/SiteFooter'
import { Statement } from '@/components/site/Statement'
import { WorkRail } from '@/components/visuals/WorkRail'
import { homeContent, homeSections, type HomeContent, type HomeSection } from '@/lib/pages/home'
import { pageSections } from '@/lib/image'
import { cn } from '@/lib/cn'

// The home page from library items (app/page.tsx): the bar, the rail of work across the upper middle of the first
// screen, and the statement at its foot with the stat line over it; the work is the page's argument and the copy is
// one sentence. `content` replaces the copy (lib/pages/home.ts); the rail's strips take your pictures.
export interface HomePageProps {
  content?: HomeContent
  /** The sections to show, in order. */
  sections?: readonly HomeSection[]
  className?: string
}

export function HomePage({ content: c = homeContent, sections, className }: HomePageProps) {
  const parts: Record<HomeSection, ReactNode> = {
    rail: <div className="flex min-h-80 flex-1 items-center py-16"><WorkRail items={c.rail} /></div>,
    statement: <Statement stat={c.stat} figure={c.figure} lead={c.lead} rest={c.rest} />,
  }
  return (
    <div data-ds="home-page" className={cn('flex min-h-screen w-full flex-col bg-surface text-fg', className)}>
      <SiteHeader {...c.header} />
      <main className="flex flex-1 flex-col">{pageSections(homeSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}</main>
      <SiteFooter links={c.footer.links} />
    </div>
  )
}

export default HomePage

import { footer, header } from '@/lib/pages/chrome'
// The home page template's copy: the rail of work and the statement under it (app/page.tsx, lib/home-content.ts),
// in the studio's words with Acme's name. The rail's strips are yours: pass `src` for each.
export const homeContent = {
	header,
	rail: Array.from({ length: 8 }, () => ({ src: '', alt: '' })),
	stat: 'Startups each batch designed by Acme:',
	figure: '6.06%',
	lead: 'Product design thinking and implementation.',
	rest: 'We help startups design their brand, product, and websites then turn it into infrastructure your engineers and agents can use to ship on-brand interfaces.',
	footer,
}
export type HomeContent = typeof homeContent
/** The home page's sections in order; pass `sections` to reorder them or leave some out. */
export const homeSections = ['rail', 'statement'] as const
export type HomeSection = (typeof homeSections)[number]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
